function canvasTexture(draw,size=256){const c=document.createElement('canvas');c.width=c.height=size;const ctx=c.getContext('2d');draw(ctx,size);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;return t;}
const woodTexture=canvasTexture((c,n)=>{c.fillStyle='#b19a79';c.fillRect(0,0,n,n);for(let i=0;i<140;i++){c.strokeStyle=`rgba(69,51,31,${.025+rnd()*.08})`;c.lineWidth=.3+rnd()*1.2;c.beginPath();const x=rnd()*n;c.moveTo(x,0);c.bezierCurveTo(x+8,rnd()*n,x-9,rnd()*n,x+3,n);c.stroke();}c.strokeStyle='#6c593929';c.strokeRect(0,0,n,n);});
const textileTexture=canvasTexture((c,n)=>{c.fillStyle='#e2d9c5';c.fillRect(0,0,n,n);for(let i=0;i<n;i+=3){c.fillStyle=i%2?'#baa98a20':'#fff8';c.fillRect(i,0,1,n);c.fillStyle='#7e75641a';c.fillRect(0,i,n,1);}});
const stoneTexture=canvasTexture((c,n)=>{c.fillStyle='#e2dfd3';c.fillRect(0,0,n,n);for(let i=0;i<6000;i++){const shade=140+Math.floor(rnd()*90);c.fillStyle=`rgba(${shade},${shade},${shade-5},.13)`;c.fillRect(rnd()*n,rnd()*n,.7,.7);}for(let i=0;i<7;i++){c.strokeStyle='#a5a39717';c.lineWidth=.7;c.beginPath();c.moveTo(rnd()*n,0);c.lineTo(rnd()*n,n);c.stroke();}});
const tileTexture=canvasTexture((c,n)=>{c.fillStyle='#cbd6cf';c.fillRect(0,0,n,n);c.strokeStyle='#eff1e5';c.lineWidth=2;for(let p=0;p<=n;p+=n/4){c.beginPath();c.moveTo(p,0);c.lineTo(p,n);c.moveTo(0,p);c.lineTo(n,p);c.stroke();}});
const screenTexture=canvasTexture((c,n)=>{const grad=c.createLinearGradient(0,0,0,n);grad.addColorStop(0,'#182c35');grad.addColorStop(.55,'#4c7474');grad.addColorStop(1,'#9aa58a');c.fillStyle=grad;c.fillRect(0,0,n,n);c.fillStyle='#e9cba3';c.beginPath();c.arc(177,78,23,0,Math.PI*2);c.fill();c.fillStyle='#243f45';c.beginPath();c.moveTo(0,185);c.lineTo(75,110);c.lineTo(133,168);c.lineTo(177,135);c.lineTo(256,203);c.lineTo(256,256);c.lineTo(0,256);c.fill();c.fillStyle='#eef1da';c.textAlign='center';c.font='10px Georgia';c.fillText('THE QUIET HOURS',128,224);c.font='4px Arial';c.fillText('YOUR PRIVATE CINEMA',128,237);});
