function mat(name,color,roughness=.8,extra={}){M[name]=new THREE.MeshStandardMaterial({color,roughness,...extra});return M[name];}
mat('wall','#e9e4d7');mat('wallOuter','#ede9df');mat('floor','#dcd8cb',.9,{map:stoneTexture});mat('wood','#c5ae8b',.75,{map:woodTexture});mat('darkWood','#76644b',.8,{map:woodTexture});mat('linen','#f0e8d7',1,{map:textileTexture});mat('olive','#b2ada1',1,{map:textileTexture});mat('sage','#a9b1a0',1,{map:textileTexture});mat('terracotta','#c3b8a9',1,{map:textileTexture});mat('charcoal','#3e4a47',.9,{map:textileTexture});mat('black','#273132',.65);mat('white','#faf7ee',.45);mat('ceramic','#f7f7f0',.25);mat('counter','#e9e6dc',.4,{map:stoneTexture});mat('metal','#a3aaa0',.25,{metalness:.75});mat('brass','#b8a074',.27,{metalness:.7});mat('glass','#c5e1d7',.1,{transparent:true,opacity:.23,depthWrite:false,metalness:.1,side:THREE.DoubleSide});mat('screen','#fff',.9,{map:screenTexture,emissive:'#9bcbce',emissiveMap:screenTexture,emissiveIntensity:.35});mat('light','#fff4c4',.5,{emissive:'#ffe6a3',emissiveIntensity:1.1});mat('leaf','#6e8260',.9);mat('leafDark','#455e42',1);mat('soil','#534839');mat('pot','#d2bca3');mat('road','#a6aaa4');M.horizon=new THREE.MeshBasicMaterial({color:'#e9e7df'});mat('grass','#a6b095');mat('tile','#d6e1dc',.6,{map:tileTexture});mat('rug','#d4cbb3',1,{map:textileTexture});mat('darkRug','#66756b',1,{map:textileTexture});mat('blue','#334f61',.35,{metalness:.25});mat('water','#9caeaa',.2,{metalness:.35});
mat('clay','#a85c3e');
const boxGeo=new THREE.BoxGeometry(1,1,1),sphereGeo=new THREE.SphereGeometry(1,12,8),roundedCache=new Map();
function box(g,x,y,z,sx,sy,sz,material='wood',r=0){let geo=boxGeo;if(r){const key=[sx,sy,sz,r].join('|');if(!roundedCache.has(key)){const a=-sx/2,b=-sy/2,rr=Math.min(r,sx/2-.001,sy/2-.001);const sh=new THREE.Shape();sh.moveTo(a+rr,b);sh.lineTo(a+sx-rr,b);sh.quadraticCurveTo(a+sx,b,a+sx,b+rr);sh.lineTo(a+sx,b+sy-rr);sh.quadraticCurveTo(a+sx,b+sy,a+sx-rr,b+sy);sh.lineTo(a+rr,b+sy);sh.quadraticCurveTo(a,b+sy,a,b+sy-rr);sh.lineTo(a,b+rr);sh.quadraticCurveTo(a,b,a+rr,b);const gg=new THREE.ExtrudeGeometry(sh,{depth:sz,bevelEnabled:false,curveSegments:4,steps:1});gg.translate(0,0,-sz/2);roundedCache.set(key,gg);}geo=roundedCache.get(key);}const mesh=new THREE.Mesh(geo,typeof material==='string'?M[material]:material);if(!r)mesh.scale.set(sx,sy,sz);mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;g.add(mesh);return mesh;}
function cyl(g,x,y,z,rt,rb,h,material='wood',segments=18){const mesh=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,segments),typeof material==='string'?M[material]:material);mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;g.add(mesh);return mesh;}
function ball(g,x,y,z,sx,sy,sz,material='leaf'){const mesh=new THREE.Mesh(sphereGeo,typeof material==='string'?M[material]:material);mesh.position.set(x,y,z);mesh.scale.set(sx,sy,sz);mesh.castShadow=true;g.add(mesh);return mesh;}
function rod(g,a,b,r=.035,material='metal'){const av=new THREE.Vector3(...a),bv=new THREE.Vector3(...b),mid=av.clone().add(bv).multiplyScalar(.5);const mesh=cyl(g,mid.x,mid.y,mid.z,r,r,av.distanceTo(bv),material,8);mesh.quaternion.setFromUnitVectors(v3(0,1,0),bv.sub(av).normalize());return mesh;}
function group(g,x=0,y=0,z=0,angle=0){const n=new THREE.Group();n.position.set(x,y,z);n.rotation.y=angle;g.add(n);return n;}
function plant(g,x,z,size=1,y=0){const n=group(g,x,y,z);cyl(n,0,.45*size,0,.5*size,.38*size,.9*size,'pot');cyl(n,0,.91*size,0,.44*size,.44*size,.02,'soil');for(let i=0;i<7;i++){const a=i*Math.PI*2/7;const h=(1.3+rnd()*.8)*size;rod(n,[0,.9*size,0],[Math.sin(a)*.4*size,h,Math.cos(a)*.4*size],.025*size,'leafDark');const leaf=ball(n,Math.sin(a)*.5*size,h,Math.cos(a)*.5*size,.3*size,.75*size,.12*size,i%2?'leaf':'leafDark');leaf.rotation.z=Math.sin(a)*-.5;leaf.rotation.x=Math.cos(a)*.5;}return n;}
function rug(g,x,z,w,d,dark=false){const m=(dark?M.darkRug:M.rug).clone();m.map=m.map.clone();m.map.repeat.set(w/2,d/2);box(g,x,.07,z,w,.045,d,m);for(let i=-w/2+.12;i<w/2;i+=.18){rod(g,[x+i,.09,z-d/2-.12],[x+i,.09,z-d/2+.1],.012,dark?'olive':'linen');rod(g,[x+i,.09,z+d/2-.1],[x+i,.09,z+d/2+.12],.012,dark?'olive':'linen');}}
function lamp(g,x,z,y=1.9){cyl(g,x,y+.06,z,.34,.34,.12,'brass');rod(g,[x,y+.1,z],[x,y+1.15,z],.035,'brass');cyl(g,x,y+1.3,z,.52,.32,.7,'linen');cyl(g,x,y+1.0,z,.3,.3,.035,'light');}
function sideTable(g,x,z){box(g,x,.85,z,1.55,1.7,1.5,'wood',.05);box(g,x,1.45,z+.76,1.3,.48,.03,'darkWood');rod(g,[x-.12,1.45,z+.81],[x+.12,1.45,z+.81],.025,'brass');}
function wardrobe(g,x,z,w=7,angle=0){const n=group(g,x,0,z,angle);box(n,0,3.65,0,w,7.3,1.9,'wood');const count=Math.round(w/2);for(let i=0;i<count;i++){const xx=-w/2+(i+.5)*w/count;box(n,xx,3.68,1,w/count-.055,7.15,.08,i%2?'linen':'wood');rod(n,[xx+w/count/2-.17,3.4,1.09],[xx+w/count/2-.17,4.05,1.09],.022,'brass');}return n;}
function bed(g,x,z,king=false,flip=false){const n=group(g,x,0,z,flip?Math.PI:0),w=king?6.2:5.35,d=6.75;rug(n,0,.7,w+2.8,d+1.8);for(const xx of[-w/2+.25,w/2-.25])for(const zz of[-d/2+.25,d/2-.25])cyl(n,xx,.28,zz,.08,.07,.55,'darkWood');box(n,0,.73,0,w+.25,.65,d+.25,'wood',.13);box(n,0,1.2,0,w, .62,d,'linen',.18);box(n,0,2.0,-d/2-.15,w+1,3.2,.35,'sage',.15);for(let i=0;i<10;i++)box(n,-(w+.65)/2+i*(w+.65)/9,2.1,-d/2-.35,.025,2.6,.035,'wood');box(n,0,1.54,.85,w+.03,.13,4.9,'linen',.08);box(n,0,1.64,1.5,w+.1,.15,2.2,'olive',.09);for(let i=0;i<7;i++)box(n,0,1.72,1.5-1+i*.32,w-.2,.015,.014,'sage');for(const xx of[-w/4,w/4]){box(n,xx,1.72,-2.3,w/2-.2,.4,1.25,'white',.17);box(n,xx,1.97,-2.0,w/2-.55,.27,.75,'linen',.12);}for(const xx of[-w/2-1,w/2+1]){sideTable(n,xx,-2.35);lamp(n,xx,-2.35,1.73);}return n;}
function chair(g,x,z,angle=0,material='olive'){const n=group(g,x,0,z,angle);box(n,0,1.45,0,1.5,.25,1.55,material,.1);box(n,0,2.2,-.63,1.5,1.35,.22,material,.13);for(const xx of[-.56,.56])for(const zz of[-.55,.55])rod(n,[xx,.03,zz],[xx,1.35,zz],.045,'darkWood');return n;}
