function coffeeTable(g,x,z,w=3.6,d=2.1){box(g,x,1.05,z,w,.18,d,'counter',.08);for(const xx of[-w/2+.35,w/2-.35])for(const zz of[-d/2+.3,d/2-.3])rod(g,[x+xx,.05,z+zz],[x+xx,.97,z+zz],.035,'brass');box(g,x-.4,1.18,z,.8,.08,.6,'olive');cyl(g,x+.65,1.25,z,.22,.18,.25,'pot');}
