function tableDining(g,x,z){box(g,x,2.4,z,3.5,.18,2.8,'wood',.07);for(const xx of[-1.4,1.4])for(const zz of[-1.05,1.05])rod(g,[x+xx,.05,z+zz],[x+xx,2.3,z+zz],.04,'darkWood');for(const xx of[-1,1]){chair(g,x+xx,z+2,0,'sage');chair(g,x+xx,z-2,Math.PI,'sage');}cyl(g,x,2.7,z,.22,.18,.45,'pot');}
function kitchen(g,r){const[a,b,c,d]=r.rect;const n=group(g);const xr=(a+b)/2;box(n,xr,1.4,c+1,(b-a),2.8,2,'wood');box(n,xr,2.86,c+1,b-a+.08,.18,2.1,'counter');box(n,b-1,1.4,(c+d)/2+1,2,2.8,d-c-2,'wood');box(n,b-1,2.86,(c+d)/2+1,2.1,.18,d-c-1.95,'counter');for(let xx=a+.7;xx<b;xx+=1.7){box(n,xx,1.45,c+2.03,1.58,2.5,.05,'wood');rod(n,[xx-.25,2.35,c+2.09],[xx+.25,2.35,c+2.09],.025,'brass');}box(n,xr+1,3,c+1,1.8,.04,1.15,'metal');box(n,xr+1,3.02,c+1,1.45,.02,.9,'black');rod(n,[xr+1.7,3,c+.5],[xr+1.7,3.8,c+.5],.045,'metal');rod(n,[xr+1.7,3.8,c+.5],[xr+1.25,3.8,c+.5],.045,'metal');box(n,b-1,2.99,d-1.9,1.65,.05,2.5,'black');for(const xx of[-.37,.37])for(const zz of[-.65,.65]){const tor=new THREE.Mesh(new THREE.TorusGeometry(.22,.025,6,16),M.metal);tor.rotation.x=-Math.PI/2;tor.position.set(b-1+xx,3.04,d-1.9+zz);n.add(tor);}box(n,b-1.005,1.4,d-1.9,2.02,1.55,1.65,'black');box(n,b-2.03,1.4,d-1.9,.03,1.2,1.25,'glass');box(n,a+1.25,3.45,c+1.25,2.45,6.9,2.45,'metal',.06);box(n,a+1.25,3.2,c+2.51,2.3,.04,.03,'black');rod(n,[a+2.1,3.7,c+2.55],[a+2.1,5.1,c+2.55],.035,'black');box(n,b-1,6.5,d-1.9,1.8,.5,2.4,'metal');box(n,b-.6,8.2,d-1.9,.9,3,1,'metal');box(n,xr+1,5.7,c+.55,4,2.2,1,'linen');for(let i=0;i<3;i++)box(n,xr-.3+i*1.3,5.7,c+1.07,.025,2.1,.03,'brass');box(n,xr+1,4.5,c+.6,4,.06,.9,'wood');box(n,b-3.4,3.25,c+1,1.2,.55,.9,'white',.05);cyl(n,b-3.4,3.53,c+1,.28,.28,.03,'black');plant(n,b-1,c+2.9,.38,2.95);}
function toilet(g,x,z){box(g,x,1.75,z-.6,1.3,2,.55,'ceramic',.14);cyl(g,x,.65,z+.05,.58,.4,1.3,'ceramic');const seat=cyl(g,x,1.32,z+.2,.66,.66,.13,'white');seat.scale.z=1.3;const hole=cyl(g,x,1.397,z+.2,.43,.43,.02,'black');hole.scale.z=1.3;box(g,x,2.8,z-.6,.22,.03,.13,'metal');}
function bathroom(g,r,spa=false){const[a,b,c,d]=r.rect,w=b-a;const n=group(g);const showerX=a+1.65,showerZ=c+1.7;box(n,showerX,.1,showerZ,3.15,.15,3.25,'ceramic');box(n,showerX,3.5,c+3.35,3.2,6.8,.04,'glass');box(n,a+3.25,3.5,showerZ,.04,6.8,3.3,'glass');rod(n,[a+3.25,.3,c+3.35],[a+3.25,6.9,c+3.35],.03,'metal');rod(n,[showerX,2,c+.18],[showerX,7,c+.18],.03,'metal');rod(n,[showerX,7,c+.18],[showerX,7,c+.7],.03,'metal');const head=cyl(n,showerX,6.97,c+.75,.35,.35,.05,'metal');const vx=b-1.1,vz=c+1.8;box(n,vx,2.15,vz,1.9,1.6,2.55,'wood',.04);box(n,vx,3,vz,2.0,.13,2.65,'counter');const basin=cyl(n,vx,3.15,vz,.57,.46,.23,'ceramic');basin.scale.z=1.3;cyl(n,vx,3.28,vz,.38,.38,.03,'water');rod(n,[vx,3.1,vz-1],[vx,3.75,vz-1],.035,'brass');rod(n,[vx,3.75,vz-1],[vx,3.75,vz-.65],.035,'brass');box(n,vx,5.5,c+.09,1.65,2.8,.09,'metal',.12);box(n,vx,5.5,c+.15,1.45,2.6,.025,'glass',.08);toilet(n,b-1.4,spa?d-5:d-1.75);rod(n,[a+.15,3.4,d-1],[a+.15,3.4,d-3],.035,'brass');box(n,a+.22,2.8,d-2,.08,1.2,1.3,'white');if(spa){box(n,(a+b)/2,.9,d-1.8,Math.min(w-1.4,6.5),1.7,2.7,'ceramic',.3);box(n,(a+b)/2,1.78,d-1.8,Math.min(w-2,5.9),.04,2.05,'water',.12);rod(n,[b-.55,1.9,d-1.8],[b-.55,2.5,d-1.8],.045,'brass');}rug(n,(a+b)/2,spa?c+5.8:d-3.4,2.6,1.5);}
