 const sharedGeometry=new Set([boxGeo,sphereGeo,...roundedCache.values()]),sharedMaterial=new Set(Object.values(M)),sharedMaps=new Set(Object.values(M).map(m=>m.map).filter(Boolean));
 const geometries=new Set(),materials=new Set();
 for(const g of Object.values(groups)){scene.remove(g);g.traverse(o=>{if(o.isMesh){if(!sharedGeometry.has(o.geometry))geometries.add(o.geometry);for(const m of(Array.isArray(o.material)?o.material:[o.material]))if(!sharedMaterial.has(m))materials.add(m);}});}
 for(const geo of geometries)geo.dispose();for(const m of materials){if(m.map&&!sharedMaps.has(m.map))m.map.dispose();m.dispose();}
