function updateVisibility(){if(!scene)return;const exterior=state.mode==='exterior';scene.background.set(state.evening?'#b4b9aa':exterior?'#b9dce9':'#e9e7df');scene.fog.color.copy(scene.background);for(const[id,g]of Object.entries(groups)){g.visible=exterior?id!=='basement':id===state.floor;g.position.y=exterior?FLOORS[id].level*H:0;}terrain.visible=exterior||state.floor==='ground';basementCourt.visible=!exterior&&state.floor==='basement';terrain.position.y=0;const down=groups.roof.getObjectByName('descending-stair');if(down)down.visible=state.mode==='walk';for(const door of doorGroups){door.mesh.visible=exterior;door.group.rotation.y=exterior?0:door.openRotation;}for(const facade of facades)facade.visible=exterior;if(outline)outline.visible=state.mode==='dollhouse';renderer.needsRender=true;for(const item of ceilings)item.mesh.visible=state.mode==='walk'&&item.floor===state.floor;for(const p of wallParts){let top=p.top;const cut=state.mode==='dollhouse'&&state.cut;if(cut){top=Math.min(top,3.1);p.mesh.visible=p.bottom<3.1;}else p.mesh.visible=true;if(top>p.bottom){p.mesh.scale.y=top-p.bottom;p.mesh.position.y=(top+p.bottom)/2;}}for(const l of lights){l.light.intensity=(l.floor===state.floor&&!exterior&&(state.mode==='walk'||state.evening))?(state.floor==='basement'?26:20):0;l.fixture.visible=state.mode==='walk'||exterior;}$('#walls-toggle').classList.toggle('active',state.cut);$('#walls-toggle').setAttribute('aria-pressed',String(state.cut));$('#walls-toggle span').textContent=state.cut?'Cutaway walls':'Full-height walls';}

