function setFloor(id,options={}){if(!FLOORS[id])return;if(!options.keepTour)stopTour();state.floor=id;state.room=null;$$('.floor-button').forEach(b=>b.classList.toggle('active',b.dataset.floor===id));const f=FLOORS[id];$('#view-eyebrow').textContent=`${f.short} / ${f.name.toUpperCase()}`;$('#view-title').textContent=f.title;$('#view-subtitle').textContent=f.subtitle;$('#mini-level').textContent=f.short;renderRoomList();renderMiniMap();renderPlan();updateVisibility();clearRoomCard();if(state.mode==='walk')enterRoom(f.rooms.find(r=>r.id==='living')||f.rooms[0],false);else if(!options.keepCamera)defaultView();updateLabels();}
function setMode(mode,options={}){if(!options.keepTour)stopTour();if(mode==='walk'&&!renderer){toast('3D could not start in this browser. The floor plans remain available.');return;}state.mode=mode;if(camera){camera.fov=mode==='walk'?68:42;camera.updateProjectionMatrix();}document.body.classList.toggle('walking',mode==='walk');document.body.classList.toggle('plan-mode',mode==='plan');document.body.classList.toggle('exterior-mode',mode==='exterior');$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-selected',String(b.dataset.mode===mode));});$('#plan-wrap').hidden=mode!=='plan';$('#walk-hud').hidden=mode!=='walk';$('#mini-map').style.display=mode==='exterior'?'none':'';$('#labels').style.display=mode==='walk'||mode==='plan'||mode==='exterior'?'none':'';if(orbit)orbit.enabled=mode==='dollhouse'||mode==='exterior';if(mode==='walk'){camTransition=null;const r=FLOORS[state.floor].rooms.find(r=>r.id===state.room)||FLOORS[state.floor].rooms.find(r=>r.id==='living')||FLOORS[state.floor].rooms[0];enterRoom(r,false);toast('Drag to look. Use WASD or arrow keys to walk. Choose a floor to change levels.');}else if(mode==='dollhouse'||mode==='exterior'){defaultView();}const f=FLOORS[state.floor];$('#view-eyebrow').textContent=mode==='exterior'?'THE COMPLETE RESIDENCE':`${f.short} / ${f.name.toUpperCase()}`;$('#view-title').textContent=mode==='exterior'?'Modern, from every angle.':f.title;$('#view-subtitle').textContent=mode==='exterior'?'Basement + two main floors + an open roof terrace.':f.subtitle;if(mode==='plan')renderPlan();updateVisibility();updateLabels();}
function renderRoomList(){const f=FLOORS[state.floor];$('#room-count').textContent=String(f.rooms.length).padStart(2,'0');$('#room-list').innerHTML=f.rooms.map(r=>`<button class="room-item ${r.id===state.room?'selected':''}" data-room="${r.id}"><span><i class="room-dot"></i>${r.name}</span><small>${feet(r.width)} × ${feet(r.depth)}</small></button>`).join('');$$('#room-list [data-room]').forEach(b=>b.onclick=()=>selectRoom(b.dataset.room,true));}
