function enterRoom(r,animate=false){if(!r.view)return;const [x,z]=r.view.point,[tx,tz]=r.view.look;const desiredYaw=Math.atan2(-(tx-x),-(tz-z));if(animate&&state.mode==='walk'){camTransition={from:camera.position.clone(),to:v3(x,5.35,z),start:performance.now(),duration:reduced?1:700,walk:true,yawFrom:yaw,yawTo:desiredYaw};}else{camera.position.set(x,5.35,z);yaw=desiredYaw;pitch=-.14;applyLook();}selectRoom(r.id,false);}
