if(r.type==='bathroom'){s+=`<rect x="${x(a+.3)}" y="${z(c+.3)}" width="29" height="31" fill="#d7e4dd" stroke="#8aa799" stroke-width=".8"/><path d="M${x(a+.3)} ${z(c+3.4)}L${x(a+3.2)} ${z(c+.3)}" stroke="#9cb5a5" stroke-width=".5"/><ellipse cx="${x(b-1.3)}" cy="${z(d-1.5)}" rx="6" ry="8" fill="#fafbf1" stroke="#adb8a4" stroke-width=".7"/>`;}
