if(r.type==='stairs'){for(let i=0;i<9;i++){s+=`<path d="M${x(a)} ${z(c+.8*i)}h35M${x(b-3.5)} ${z(c+.8*i)}h35" stroke="#929e84" stroke-width=".7"/>`;}s+=`<path d="M${x(a+1.7)} ${z(c+.7)}v60h40v-60" stroke="#7a8e6a" fill="none" stroke-width="1"/><text x="${x(a+1.7)}" y="${z(c+2)}" text-anchor="middle" font-size="9" fill="#718765">↑</text>`;}
if(r.type==='parking'){const shift=f.furniture.parkingStart>0?f.furniture.parkingStart+.9:0;s+=`<rect x="${x(-18)}" y="${z(-.4+shift)}" width="56" height="137" rx="12" fill="#afbaaa" stroke="#889a7a" stroke-width="1"/><rect x="${x(-17.6)}" y="${z(3+shift)}" width="48" height="60" rx="8" fill="#728477"/>`;}
if(r.type==='cinema'){s+=`<path d="M${x(a+2)} ${z(c+.7)}H${x(b-2)}" stroke="#425e5f" stroke-width="4"/>`;for(let row=0;row<2;row++)for(let i=0;i<(state.design%2===0?2:3);i++)s+=`<rect x="${x(a+(state.design%2===0?5.3+i*7.8:3.7+i*5.4)-1.85)}" y="${z(c+4.85+row*4.2)}" width="32" height="25" rx="4" fill="#64776b"/>`;}
if(r.id==='family-dining'){const[dx,dz]=f.furniture.dining;s+=`<rect x="${x(dx-1.75)}" y="${z(dz-1.4)}" width="35" height="28" rx="2" fill="#c2af8e"/>`;for(const xx of[-1,1])for(const zz of[-2,2])s+=`<rect x="${x(dx+xx)-6}" y="${z(dz+zz)-6}" width="12" height="12" fill="#a9b1a0"/>`;}
if(r.type==='living'){if(f.furniture.custom){const ss=f.furniture.sofa,tt=f.furniture.tv;s+=`<rect x="${x(ss.x-ss.width/2)}" y="${z(ss.z-1.35)}" width="${ss.width*10}" height="27" rx="3" fill="#b6bfaa"/><path d="M${x(tt.x-tt.width/2)} ${z(tt.z)}H${x(tt.x+tt.width/2)}" stroke="#425e5f" stroke-width="3"/>`;}else{s+=`<rect x="${x(-.25)}" y="${z(6)}" width="28" height="73" rx="3" fill="#b6bfaa"/>`;}}
if(r.type==='drawing'||r.type==='balcony')s+=`<rect x="${x(a+1)}" y="${z(c+2)}" width="${Math.max(20,r.width*scale-25)}" height="21" rx="3" fill="#b6bfaa" stroke="#8b9d7e" stroke-width=".7"/>`;
if(r.type==='prayer')for(let i=0;i<3;i++)s+=`<rect x="${x(a+(i+.5)*r.width/3-1.2)}" y="${z(c+5)}" width="24" height="47" rx="2" fill="#a2b58d" stroke="#8a9e77"/>`;
