function renderMiniMap(){$('#mini-svg').innerHTML=planSVG(true);}
function renderPlan(){$('#plan-wrap').innerHTML=planSVG(false);$$('#plan-wrap [data-room]').forEach(e=>e.onclick=()=>selectRoom(e.dataset.room,true));}

function updateLabels(){if(!camera)return;const allowed=state.mode==='dollhouse'&&state.labels;const distance=camera.position.distanceTo(orbit.target);for(const l of roomLabels){const visible=allowed&&l.floor===state.floor&&distance<160;if(!visible){l.element.style.display='none';continue;}const p=l.position.clone().project(camera);const xx=(p.x*.5+.5)*width,yy=(-p.y*.5+.5)*height;const inView=p.z<1&&xx>10&&xx<width-10&&yy>65&&yy<height-55;l.element.style.display=inView?'block':'none';l.element.style.left=xx+'px';l.element.style.top=yy+'px';l.element.style.opacity=distance>110?.65:1;}}

function setupInput(){host.addEventListener('pointerdown',e=>{pointerStart=[e.clientX,e.clientY];lastPointer=pointerStart;moved=false;if(state.mode==='walk'){dragging=true;host.setPointerCapture(e.pointerId);}});host.addEventListener('pointermove',e=>{if(pointerStart&&Math.hypot(e.clientX-pointerStart[0],e.clientY-pointerStart[1])>4)moved=true;if(state.mode==='walk'&&dragging&&lastPointer){yaw-=(e.clientX-lastPointer[0])*.004;pitch=clamp(pitch-(e.clientY-lastPointer[1])*.003,-1.35,1.35);applyLook();lastPointer=[e.clientX,e.clientY];camTransition=null;}});host.addEventListener('pointerup',e=>{dragging=false;lastPointer=null;if(!moved&&state.mode==='dollhouse'){const rect=host.getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);pickRay.setFromCamera(pointer,camera);const objects=roomMeshes.filter(o=>o.userData.floor===state.floor);const hits=pickRay.intersectObjects(objects);if(hits.length)selectRoom(hits[0].object.userData.room,false);}pointerStart=null;});host.addEventListener('pointercancel',()=>{dragging=false;lastPointer=null;pointerStart=null;});document.addEventListener('keydown',e=>{if($('#notes-dialog').open)return;const key=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright','w','a','s','d','q','e','escape'].includes(key)){if(state.mode==='walk'){e.preventDefault();if(key==='escape')setMode('dollhouse');else if(key==='e'||key==='q'){const fs=['basement','ground','first','roof'],next=fs.indexOf(state.floor)+(key==='e'?1:-1);if(fs[next])setFloor(fs[next]);}else keys.add(key);}}});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();dragging=false;});$$('[data-move]').forEach(b=>{const map={forward:'w',back:'s',left:'a',right:'d'};const key=map[b.dataset.move];b.onpointerdown=e=>{e.preventDefault();keys.add(key);b.setPointerCapture(e.pointerId);};b.onpointerup=b.onpointercancel=()=>keys.delete(key);});}
function canWalk(x,z){if(x<-20.25||x>20.25||z<-15.1||z>15.1)return false;return ![...colliders[state.floor],...furnitureBlocks[state.floor]].some(r=>x>r.x1&&x<r.x2&&z>r.z1&&z<r.z2);}
function walkUpdate(dt){if(state.mode!=='walk'||camTransition)return;let forward=(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0),right=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0);if(!forward&&!right)return;const norm=Math.hypot(forward,right);forward/=norm;right/=norm;const speed=6*dt,dx=(-Math.sin(yaw)*forward+Math.cos(yaw)*right)*speed,dz=(-Math.cos(yaw)*forward-Math.sin(yaw)*right)*speed;const nx=camera.position.x+dx,nz=camera.position.z+dz;if(canWalk(nx,camera.position.z))camera.position.x=nx;if(canWalk(camera.position.x,nz))camera.position.z=nz;if(frame%8===0){const r=FLOORS[state.floor].rooms.find(r=>camera.position.x>r.rect[0]&&camera.position.x<r.rect[1]&&camera.position.z>r.rect[2]&&camera.position.z<r.rect[3]);if(r&&r.id!==state.room)selectRoom(r.id,false);renderMiniMap();}}
function startTour(){stopTour();state.tour=true;state.tourIndex=0;state.tourPaused=false;document.body.classList.add('touring');$('#tour-bar').hidden=false;$('#tour-pause').textContent='Ⅱ';tourStop();}
function tourStop(){const[id,room]=TOUR[state.tourIndex];setFloor(id,{keepTour:true,keepCamera:true});setMode('walk',{keepTour:true});selectRoom(room,true);$('#tour-progress').textContent=`GUIDED TOUR / ${String(state.tourIndex+1).padStart(2,'0')} OF ${TOUR.length}`;$('#tour-place').textContent=FLOORS[id].rooms.find(r=>r.id===room).name;clearTimeout(tourTimer);if(!state.tourPaused)tourTimer=setTimeout(nextTour,8000);}
function nextTour(){if(!state.tour)return;if(state.tourIndex>=TOUR.length-1){stopTour();toast('Tour complete. Keep exploring any floor.');return;}state.tourIndex++;tourStop();}
function stopTour(){clearTimeout(tourTimer);state.tour=false;document.body.classList.remove('touring');$('#tour-bar').hidden=true;}

function setupUI(){$$('[data-design]').forEach(b=>b.onclick=()=>switchDesign(b.dataset.design));refreshDesignControls();$('#gate-toggle').onclick=togglePedestrianGate;$$('.floor-button').forEach(b=>b.onclick=()=>setFloor(b.dataset.floor));$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$('#enter-home').onclick=()=>setMode('walk');$('#room-enter').onclick=()=>setMode('walk');$('#mini-plan').onclick=()=>setMode('plan');$('#walk-exit').onclick=()=>setMode('dollhouse');$('#walls-toggle').onclick=()=>{state.cut=!state.cut;updateVisibility();};$('#labels-toggle').onclick=()=>{state.labels=!state.labels;$('#labels-toggle').classList.toggle('active',state.labels);$('#labels-toggle').setAttribute('aria-pressed',String(state.labels));updateLabels();};$('#reset-view').onclick=()=>{state.room=null;renderRoomList();clearRoomCard();if(state.mode==='walk')setMode('dollhouse');else defaultView();};$('#lighting').onclick=()=>{state.evening=!state.evening;$('#lighting').innerHTML=state.evening?'☾ <span>Evening</span>':'☀ <span>Daylight</span>';$('#lighting').setAttribute('aria-label',state.evening?'Switch to daylight':'Switch to evening lighting');if(scene){scene.background.set(state.evening?'#b4b9aa':'#e9e7df');scene.fog.color.copy(scene.background);ambient.intensity=state.evening?.9:2.5;sky.intensity=state.evening?1:2.2;sun.intensity=state.evening?1.2:3.4;sun.color.set(state.evening?'#ffd4a0':'#fff7e8');renderer.toneMappingExposure=state.evening?1.15:1.0;updateVisibility();}};$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Full screen is unavailable here. Open the site in its own tab.');}};$('#zoom-in').onclick=()=>zoom(.83);$('#zoom-out').onclick=()=>zoom(1.2);$('#notes-open').onclick=()=>$('#notes-dialog').showModal();$('#notes-close').onclick=()=>$('#notes-dialog').close();$('#notes-dialog').addEventListener('click',e=>{if(e.target===$('#notes-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});$('#download-plan').onclick=()=>{const blob=new Blob([planSVG(false)],{type:'image/svg+xml'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`Courtyard-design-${state.design}-${state.floor}-concept-plan.svg`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Floor plan downloaded. Dimensions are conceptual.');};$('#tour-start').onclick=startTour;$('#tour-next').onclick=nextTour;$('#tour-close').onclick=stopTour;$('#tour-pause').onclick=()=>{state.tourPaused=!state.tourPaused;$('#tour-pause').textContent=state.tourPaused?'▷':'Ⅱ';$('#tour-pause').setAttribute('aria-label',state.tourPaused?'Resume tour':'Pause tour');clearTimeout(tourTimer);if(!state.tourPaused)tourTimer=setTimeout(nextTour,8000);};}
function zoom(factor){if(!camera||state.mode==='walk')return;const direction=camera.position.clone().sub(orbit.target).multiplyScalar(factor);if(direction.length()>25&&direction.length()<165){camera.position.copy(orbit.target).add(direction);camTransition=null;}}

function init(){try{const canvas=document.createElement('canvas');const context=canvas.getContext('webgl2',{antialias:true,alpha:false,powerPreference:'high-performance'});if(!context)throw new Error('Software 3D selected');renderer=new THREE.WebGLRenderer({canvas,context,antialias:true,alpha:false});}catch(error){renderer=new SoftwareRenderer();document.body.classList.add('software-3d');}renderer.setPixelRatio(Math.min(devicePixelRatio,1.75));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1;renderer.outputColorSpace=THREE.SRGBColorSpace;host.appendChild(renderer.domElement);scene=new THREE.Scene();scene.background=new THREE.Color('#e9e7df');scene.fog=new THREE.Fog('#e9e7df',130,260);camera=new THREE.PerspectiveCamera(42,1,.08,500);orbit=new OrbitControls(camera,renderer.domElement);orbit.enableDamping=true;orbit.dampingFactor=.07;orbit.minDistance=25;orbit.maxDistance=165;orbit.minPolarAngle=.08;orbit.maxPolarAngle=Math.PI*.485;orbit.target.set(0,0,0);orbit.addEventListener('start',()=>{camTransition=null;});sun=new THREE.DirectionalLight('#fff7e8',3.4);sun.position.set(-45,65,36);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-50;sun.shadow.camera.right=50;sun.shadow.camera.top=60;sun.shadow.camera.bottom=-50;sun.shadow.camera.near=1;sun.shadow.camera.far=170;sun.shadow.normalBias=.05;sun.shadow.bias=-.00015;sun.shadow.radius=3;scene.add(sun);ambient=new THREE.AmbientLight('#fff8df',2.5);scene.add(ambient);sky=new THREE.HemisphereLight('#e8efe9','#aaa48d',2.2);scene.add(sky);for(const id of Object.keys(FLOORS))buildFloor(id);buildTerrain();const ground=new THREE.Mesh(new THREE.PlaneGeometry(1000,1000),M.horizon);ground.rotation.x=-Math.PI/2;ground.position.y=-H-.9;ground.receiveShadow=true;scene.add(ground);setupUI();setupInput();try{const saved=Number(localStorage.getItem('courtyard-design'));if(saved>=1&&saved<=4&&saved!==1)switchDesign(saved);}catch{}defaultView(false);setFloor('ground',{keepCamera:true});const obs=new ResizeObserver(resize);obs.observe(viewer);resize();window.__courtyard={state,FLOORS,groups,colliders,furnitureBlocks,renderer,camera,selectRoom,setFloor,setMode,canWalk,planSVG,switchDesign};renderer.setAnimationLoop(animate);requestAnimationFrame(()=>{$('#loading').style.opacity='0';setTimeout(()=>$('#loading').style.display='none',600);});}
function resize(){width=viewer.clientWidth;height=viewer.clientHeight;if(renderer){renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix();}updateLabels();}
function animate(now){frame++;const dt=Math.min((now-previous)/1000,.12);previous=now;if(camTransition){const t=clamp((now-camTransition.start)/camTransition.duration,0,1),ease=t*t*(3-2*t);camera.position.lerpVectors(camTransition.from,camTransition.to,ease);if(camTransition.walk){const dy=Math.atan2(Math.sin(camTransition.yawTo-camTransition.yawFrom),Math.cos(camTransition.yawTo-camTransition.yawFrom));yaw=camTransition.yawFrom+dy*ease;pitch=-.14;applyLook();}else{orbit.target.lerpVectors(camTransition.targetFrom,camTransition.targetTo,ease);}if(t>=1)camTransition=null;}if(state.mode==='walk'){walkUpdate(dt);applyLook();if(state.tour&&!state.tourPaused&&!camTransition){yaw+=dt*.018;applyLook();}}else if(state.mode!=='plan')orbit.update();if(frame%2===0)updateLabels();renderer.render(scene,camera);}

init();
